// Generated By: Claude Code (Claude Opus 4.6)
//
// Workflow script for review skill concern agent dispatch.
// Schema enforcement via agent(schema:) — structural, not persuasive.
//
// args: {
//   agentOutputSchema: object,    // cleaned agent-output schema (workflow-safe)
//   dimensions: [{name, slug, scope}],
//   projectRoot: string,
//   pluginHome: string,
//   projectContext: {language, buildSystem, testFramework},
//   standards: string,            // local standards text (from CLAUDE.md etc)
//   prScope: string,              // PR scope output or empty
//   userGuidance: string,         // user guidance output or empty
//   allowlist: string,            // allowed commands text or empty
//   buildPrompt: string,          // prompt for build-checks agent
// }

export const meta = {
  name: 'review-concern-agents',
  description: 'Dispatch concern agents with schema-enforced structured output',
  phases: [
    { title: 'Build', detail: 'Run make check targets' },
    { title: 'Review', detail: 'Concern agents per dimension', model: 'sonnet' },
  ],
}

const CONCERNS = [
  { concern: 'Architecture & Design', slug: 'architecture', model: 'sonnet',
    scope: 'Project structure, module boundaries, coupling, data model, configuration management, design pattern consistency.' },
  { concern: 'Implementation Quality', slug: 'implementation', model: 'sonnet',
    scope: 'Logic correctness, error handling, type safety, resource management, edge cases, concurrency. Security excluded.' },
  { concern: 'Test Quality & Coverage', slug: 'test', model: 'sonnet',
    scope: 'Test plan alignment, isolation, assertion quality, edge case coverage, mock usage, missing scenarios, fixture design.' },
  { concern: 'Maintainability & Standards', slug: 'maintainability', model: 'sonnet',
    scope: 'Naming, duplication, import organization, function complexity, internal consistency, build system. Documentation excluded.' },
  { concern: 'Security', slug: 'security', model: 'sonnet',
    scope: 'Authn/authz, input validation, injection vectors, credential/secret handling, path traversal, deserialization, supply chain, TLS/crypto. Auth chain rule: verify full auth chain before reporting filter-level IDOR.' },
  { concern: 'Documentation', slug: 'documentation', model: 'haiku',
    scope: 'README accuracy, docstrings, inline comments where non-obvious, examples, ADRs, changelog, public API docs, install/usage instructions.' },
  { concern: 'Observability', slug: 'observability', model: 'haiku',
    scope: 'Log quality (levels, structured fields, sensitive data), error context, metrics, traces, debug affordances, alerting hooks.' },
]

function buildConcernPrompt(concern, dimension) {
  const prScopeBlock = args.prScope ? '\nPR SCOPE:\n' + args.prScope + '\n' : ''
  const guidanceBlock = args.userGuidance ? '\nUSER GUIDANCE:\n' + args.userGuidance + '\n' : ''
  const standardsBlock = args.standards ? '\nLOCAL STANDARDS:\n' + args.standards + '\n' : ''
  const allowlistBlock = args.allowlist ? '\nALLOWED COMMANDS:\n' + args.allowlist + '\n' : ''
  const sharedInfra = dimension.scope.shared_infrastructure
    ? '\nThis dimension covers shared infrastructure files modified in the PR. Only report findings INTRODUCED or EXPOSED by this PR — not pre-existing issues.\n'
    : ''

  return `You are reviewing the project at ${args.projectRoot} for the **${concern.concern}** axis within the dimension **${dimension.name}** (slug: ${dimension.slug}).

DIMENSION SCOPE (confine your review to this):
${JSON.stringify(dimension.scope)}
${sharedInfra}
If you notice issues clearly outside this scope, list them under cross_cutting_observations but do not investigate deeply.

PROJECT CONTEXT:
- Language: ${args.projectContext.language}
- Build system: ${args.projectContext.buildSystem}
- Test framework: ${args.projectContext.testFramework}
${allowlistBlock}${standardsBlock}${prScopeBlock}${guidanceBlock}
METHODOLOGY:
Phase 1 — Establish baseline patterns:
Read enough code in scope to understand the project's existing conventions for the ${concern.concern} axis.

Phase 2 — Assess against baseline:
Evaluate whether the codebase follows its own patterns consistently. Flag deviations, gaps, and concrete issues.

FINDING CLASSIFICATION — five categorical dimensions, each requires a value AND a _justification string:

- runtime_scope: documentation | tooling | ci | service-internal | service-external
  Test coverage gaps use ci. Use service-* only for production runtime defects.

- failure_mode: unclear | confusion | build-break | degraded-behavior | crash-or-outage | data-loss-or-security
  Must be CURRENT, not hypothetical. Use unclear for coverage/observability gaps.

- evidence_quality: speculative | inferred | demonstrated
  demonstrated requires demonstrating a FAILURE, not the absence of a test.

- trace_origin: local | component | entry-point
  entry-point must name the entry point and trace to a problematic outcome.
  Test coverage gaps use local.

- effort_to_fix: trivial | small | moderate | large

SPLIT test gaps from production defects — they are separate findings with different dimensions.
Do NOT drop speculative findings.

CRITICAL FIELD RULES:
- locations[].line: STRING not integer. Write "42" not 42. Ranges OK: "12-20"
- locations[].path: repo-relative POSIX path
- locations[].role: optional, one of "primary", "related", "callsite", "requirement"
- Every finding needs at least one location
- For "X is missing" findings, cite the spec/standards where the requirement is stated with role: "requirement"

HARD EXCLUSIONS — never report:
- Style issues enforced by linters/formatters
- Missing tests for trivial code (getters/setters/data classes)
- Architecture concerns in scripts/ or one-off utilities
- Issues already caught by make targets
- Missing docstrings on private functions
- Generic best-practice advice not grounded in a specific code location
- Positive observations or praise. Every finding must describe a problem.
  If suggested_fix would say "no action needed" or "continue doing this", it is NOT a finding.
  Positive patterns belong in cross_cutting_observations.

PROHIBITED ACTIONS:
- Do NOT modify any source code or tests
- Do NOT execute the user's program
- Do NOT install or upgrade packages

Your output must include: agent_id (use "${concern.slug}/${dimension.slug}"), concern, concern_slug, dimension_name, dimension_slug, dimension_scope, and findings array. Optionally include cross_cutting_observations.`
}

// Phase 1: Build checks
phase('Build')
const buildResult = await agent(args.buildPrompt, {
  label: 'build-checks',
  model: 'haiku',
  phase: 'Build',
})

// Phase 2: Concern agents with schema enforcement
phase('Review')
log('Dispatching ' + (args.dimensions.length * CONCERNS.length) + ' concern agents with schema enforcement')

const results = await parallel(
  args.dimensions.flatMap(dim =>
    CONCERNS.map(c => () =>
      agent(buildConcernPrompt(c, dim), {
        label: c.slug + '/' + dim.slug,
        model: c.model,
        phase: 'Review',
        schema: args.agentOutputSchema,
      }).then(output => output ? {
        concern_slug: c.slug,
        dimension_slug: dim.slug,
        filename: c.slug + '-' + dim.slug + '.json',
        output: output,
      } : null)
    )
  )
)

const succeeded = results.filter(Boolean)
const failed = results.length - succeeded.length
log(succeeded.length + '/' + results.length + ' agents returned valid output' + (failed > 0 ? ' (' + failed + ' failed)' : ''))

return {
  buildResult: buildResult,
  agentOutputs: succeeded,
  totalDispatched: results.length,
  failedCount: failed,
}
